void Solver::bump_var(int var, double coeff) {
    // Compute increment
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale only when necessary (much less frequent than original)
    const double THRESH = 1e150;   // very high threshold to avoid frequent full scans
    const double SCALE  = 1e-150;  // reciprocal scaling factor

    // If either the global increment or this variable's activity exploded, rescale everything
    if (var_inc > THRESH || activity[var] > THRESH) {
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
